import {estimate,credibility,matches,VEHICLES,fuelRate,tripPrice,LINK_KINDS,cleanLinks} from './domain.mjs';
import {outline,tripAlerts,calendar} from './travel.mjs';
const $=s=>document.querySelector(s), main=$('#main'), modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>'₹'+Math.round(x).toLocaleString('en-IN');
const photo=id=>`assets/${id}.jpg`;
const ownLinks=g=>Object.entries(g.links||{}).map(([k,href])=>`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${LINK_KINDS[k].label} ↗</a>`).join('');
const providerName=()=>({google:'Google',password:'email'})[session.user?.provider]||'ChatGPT';
const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const travelWindow=t=>t.months.map(m=>MONTHS[m].slice(0,3)).join(', ');
const vehicleLabel=type=>type==='Bike'?'♧ Bike':'▱ Car';
const allGroups=()=>[...directoryGroups,...sampleGroups,...state.groups];
const isSample=id=>sampleGroups.some(x=>x.id===id);
import {trips} from './catalog.mjs';
const sampleGroups=[{id:'weekend',name:'The Weekend Wanderers',city:'Bengaluru',vehicle:'Bike',members:248,icon:'♧',profile:100,completion:94,reviews:96,description:'Easy Saturday rides, breakfast stops, and a crew that waits for everyone.'},{id:'overland',name:'Overland Collective',city:'Mumbai',vehicle:'Car',members:186,icon:'⌁',profile:95,completion:92,reviews:96,description:'Thoughtful road trips for people who love the long way around.'},{id:'himalayan',name:'Himalayan Trail Riders',city:'Delhi',vehicle:'Bike',members:312,icon:'△',profile:100,completion:90,reviews:94,description:'Mountain enthusiasts sharing preparation, riding skills, and memorable routes.'}];
const directoryGroups=[
{id:'ibrmc',name:'India Bull Riders Motorcycle Club',city:'Delhi NCR · Mumbai · Bengaluru · Chennai + chapters',vehicle:'Bike',external:true,website:'https://indiabullriders.com/chapters/',description:'Motorcycle club with a chapter directory and group-ride activities. Check the official chapter page for local membership and current ride contacts.'},
{id:'xbhp',name:'xBhp motorcycling community',city:'India · online community',vehicle:'Bike',external:true,website:'https://www.xbhp.com/',description:'Motorcycling community and publication with rider discussions and travel stories. Use the official platform to find current local activity.'},
{id:'enfield-community',name:'Enfield Rider’s Community',city:'Kolkata · Assam · Bengaluru',vehicle:'Bike',external:true,website:'https://www.enfieldriderscommunity.com/',description:'Adventure touring community focused on Royal Enfield motorcycles. Check its official site for current rides and participation requirements.'}
];
// shortcut: trip and group data remains browser-local; add shared storage when cross-device sync is needed.
let session = {user:null, signInUrl:'/signin-with-chatgpt?return_to=%2F', signOutUrl:'/signout-with-chatgpt?return_to=%2F'};
let authLoading=true, authError=false;
let storageKey='roamly-v2:guest';
let state={saved:[],joined:[],groups:[],alerts:[]};
let garage=null, garageDraft=null, aiAvailable=false, latestPlan=null;
function loadState(){
  storageKey='roamly-v2:'+ (session.user ? session.user.id : 'guest');
  let saved;try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{saved={}}
  if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
  state={alerts:Array.isArray(saved.alerts)?saved.alerts.filter(a=>a&&typeof a.id==='string'&&typeof a.label==='string'&&Number.isFinite(Date.parse(a.at))):[],saved:Array.isArray(saved.saved)?saved.saved.filter(x=>typeof x==='string'):[],joined:Array.isArray(saved.joined)?saved.joined.filter(x=>typeof x==='string'):[],groups:Array.isArray(saved.groups)?saved.groups.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&typeof x.city==='string'&&['Bike','Car'].includes(x.vehicle)).map(x=>({...x,links:cleanLinks(x.links).links||{}})):[]};
}
async function loadSession(){
  try{
    const response=await fetch('/api/session',{cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(10000)});
    if(!response.ok)throw new Error('Session unavailable');
    const result=await response.json();
    if(result.user && (typeof result.user.id!=='string'||typeof result.user.name!=='string'))throw new Error('Invalid session');
    session={...session,user:result.user||null,signOutUrl:result.signOutUrl||session.signOutUrl,googleLogin:result.googleLogin===true};
  }catch{authError=true}
  authLoading=false;loadState();render();checkAlerts();if(session.user)loadGarage().then(ok=>{if(ok&&!garage.updatedAt){garageDraft=structuredClone(garage.profile);open('<h2>Welcome to Roamly.</h2>');renderProfile()}if(ok&&$('#plan-garage'))$('#plan-garage').innerHTML='<option value="">Use manual assumptions</option>'+garage.profile.vehicles.map(v=>`<option value="${esc(v.id)}">${esc(v.make+' '+v.model)} · ${v.type}</option>`).join('')});fetch('/api/ai-plan').then(r=>r.json()).then(x=>{aiAvailable=x.available===true;if(aiAvailable&&$('.view-intro .demo-label'))$('.view-intro .demo-label').textContent='AI SUGGESTIONS AVAILABLE · REVIEW BEFORE TRAVEL';if(aiAvailable&&$('#request-ai')&&latestPlan.data.days<=30)$('#request-ai').disabled=false}).catch(()=>{});
}
let page='discover',filter={query:'',vehicle:'All',season:'All'}, toastTimer;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes will last for this session.')}updateProfile()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800)}
function updateProfile(){
  $('#saved-count').textContent=state.saved.length;
  $('#profile-label').innerHTML=authLoading?'Checking sign-in…<small>Please wait</small>':session.user?`${esc(session.user.name)}<small>Signed in with ${providerName()}</small>`:authError?'Sign-in unavailable<small>Tap to retry</small>':'Guest explorer<small>Sign in or register</small>';
  const top=$('#auth-button');top.textContent=authLoading?'Checking sign-in…':session.user?'My account':'Sign in';top.disabled=authLoading;
}
function open(content){$('#modal-body').innerHTML=content;modal.showModal()}
function heading(title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">THE WORLD LOOKS BETTER FROM THE ROAD</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function tripCard(t){return `<article class="trip-card"><div class="card-photo"><img src="${photo(t.image)}" alt="Illustrative landscape for this trip idea" loading="lazy"><span class="card-tag">${vehicleLabel(t.vehicle)} trip</span><button class="save ${state.saved.includes(t.id)?'saved':''}" data-save="${t.id}" aria-label="${state.saved.includes(t.id)?'Unsave':'Save'} ${esc(t.title)}" aria-pressed="${state.saved.includes(t.id)}">${state.saved.includes(t.id)?'♥':'♡'}</button><span class="photo-bottom">${t.level==='Easy going'?'◌':'↗'} ${t.level}</span></div><div class="card-body"><button class="card-action" data-trip="${t.id}"><div class="card-location">⌖ ${t.location}</div><h3>${t.title}</h3><div class="trip-meta"><span>▦ ${t.days} days</span><span>⌁ ${t.km} km</span></div></button><div class="card-separator"></div><div class="card-bottom"><span class="price">${money(tripPrice(t))} <small>/ person · 2 travelers</small></span><button class="text-link" data-trip="${t.id}">Explore ↗</button></div></div></article>`}
function groupRow(g,full=false){if(g.external)return `<article class="group-row"><div class="group-logo">♧</div><div class="group-info"><h3><button class="card-action" data-group="${esc(g.id)}">${esc(g.name)} ↗</button></h3><p>${esc(g.city)} · ${g.vehicle}</p></div><span class="credibility">Unrated</span><a class="join" href="${g.website}" target="_blank" rel="noopener noreferrer">Official site ↗</a>${full?`<div class="group-detail">${esc(g.description)}<br><span class="social-empty">Public directory reference · no imported membership or affiliation</span></div>`:''}</article>`;const joined=state.joined.includes(g.id),sample=isSample(g.id);return `<article class="group-row"><div class="group-logo">${esc(g.icon||'♧')}</div><div class="group-info"><h3><button class="card-action" data-group="${esc(g.id)}">${esc(g.name)} ↗</button></h3><p>⌖ ${esc(g.city)} · ${Number(g.members)+(joined?1:0)} members · ${g.vehicle}</p></div><button class="credibility" data-score="${esc(g.id)}" title="See credibility signals">♢ ${sample?credibility(g)+' / 100':'Unrated'}</button><button class="join" data-join="${esc(g.id)}">${joined?'Joined ✓':'Join +'}</button>${full?`<div class="group-detail">${esc(g.description)}<br><span class="social-empty">${sample?'Sample community · no live social connection':'Your demo community · stored in this browser'}</span></div><div class="group-links">${ownLinks(g)||`<a href="https://www.instagram.com/explore/search/keyword/?q=${encodeURIComponent(g.city+' '+g.vehicle+' road trip')}" target="_blank" rel="noopener noreferrer">Search Instagram ↗</a><a href="https://www.facebook.com/search/groups/?q=${encodeURIComponent(g.city+' road trip')}" target="_blank" rel="noopener noreferrer">Search Facebook groups ↗</a>`}</div>`:''}</article>`}
function discover(){return heading('Find your road. Find your people.','Extraordinary routes. Like-minded explorers. One unforgettable journey.',`<div class="date-note"><span>☀</span> A little wanderlust looks good on you.</div>`)+`<section class="hero"><img src="${photo('photo-1464822759023-fed622ff2c3b')}" alt="Sunlight over a dramatic green mountain valley"><div class="hero-content"><span class="hero-tag">FOR THE LOVE OF THE OPEN ROAD</span><h2>Take the scenic route.<br>Make a better story.</h2><p>Two wheels or four. Mountains or coastlines.<br>Your kind of adventure, with your kind of people.</p><button class="primary" data-page="planner">✧ Plan my next escape <span style="margin-left:16px">↗</span></button></div><div class="hero-caption">⌖ Somewhere worth getting lost.<small>Illustrative landscape</small></div></section><form class="search-panel" id="search-form"><div class="search-field"><label for="destination">WHERE TO?</label><input id="destination" name="query" placeholder="⌖  A place, a route, a little escape" value="${esc(filter.query)}" maxlength="100"></div><div class="search-field"><label for="vehicle">YOUR RIDE</label><select id="vehicle" name="vehicle"><option value="All">Bike or car</option><option>Bike</option><option>Car</option></select></div><div class="search-field"><label for="season">WHEN'S THE ADVENTURE?</label><select id="season" name="season"><option value="All">Any season</option><option>Winter</option><option>Summer</option><option>Monsoon</option><option>Autumn</option></select></div><button class="primary">Find my trip ↗</button></form><section><div class="section-heading"><div><h2>16 routes. Countless stories.</h2><p>Handpicked escapes for your next out-of-office.</p></div><div class="pills">${['All','Bike','Car'].map(v=>`<button class="pill ${filter.vehicle===v?'active':''}" data-filter="${v}">${v==='All'?'All trips':vehicleLabel(v)}</button>`).join('')}</div></div><div id="results-info" class="results-info"></div><div class="trip-grid" id="trip-results"></div></section><div class="lower-grid"><section><div class="section-heading"><div><h2>Your people are out there.</h2><p>Find a crew that shares your kind of adventure.</p></div><button class="text-link" data-page="groups">All communities ↗</button></div><div class="group-list">${[...directoryGroups,...sampleGroups].slice(0,2).map(g=>groupRow(g)).join('')}</div></section><section><div class="section-heading"><div><h2>Right place. Right season.</h2><p>A little timing makes a big difference.</p></div></div><div class="season-card"><div class="eyebrow">THE SEASONAL EDIT · OCT — FEB</div><h3>Cooler days.<br>Warmer memories.</h3><p>Follow the coast or head for the desert.<br>Find your next winter escape.</p><span class="season-icon">✳</span><button class="text-link" data-season="Winter">Explore winter routes ↗</button><div class="season-tags"><span>☀ Rajasthan</span><span>≈ Konkan coast</span><span>♧ Coorg</span></div></div></section></div>`}
function updateTrips(){const result=trips.filter(t=>matches(t,filter));$('#trip-results').innerHTML=result.length?result.map(tripCard).join(''):'<div class="empty">No matching routes yet. Try another place, vehicle, or season.</div>';$('#results-info').textContent=`${result.length} curated route${result.length===1?'':'s'} · distances and budgets are estimates${filter.season!=='All'?' · '+filter.season:''}`;$('#vehicle').value=filter.vehicle;$('#season').value=filter.season}
function planner(){return heading('A great trip starts with a little planning.','Places to explore, somewhere to pause, and a budget for everyone.')+`<div class="view-intro"><h2>Meet your trip co-pilot. ✧</h2><p>Choose a route, your vehicle and travel style. Plan sightseeing, breaks, stay areas and costs per person.</p><span class="demo-label">${aiAvailable?'AI SUGGESTIONS AVAILABLE · REVIEW BEFORE TRAVEL':'CURATED SUGGESTIONS · LIVE AI AWAITS SERVICE SETUP'}</span></div><div class="planner-layout"><form id="planner-form" class="panel"><h3>Make it your kind of journey</h3><div class="form-grid"><div class="form-field wide"><label for="plan-route">Route</label><select name="route" id="plan-route">${trips.map(t=>`<option value="${t.id}">${t.route}</option>`).join('')}</select></div><div class="form-field wide"><label for="plan-garage">Vehicle from your garage</label><select id="plan-garage" name="garage"><option value="">Use manual assumptions</option>${(garage?.profile.vehicles||[]).map(v=>`<option value="${esc(v.id)}">${esc(v.make+' '+v.model)} · ${v.type} · ${v.mileage} ${v.fuel==='Electric'?'km/kWh':'km/l'}</option>`).join('')}</select><button type="button" class="text-link" id="planner-profile">Manage my profile & vehicles ↗</button></div><div class="form-field"><label for="plan-vehicle">Vehicle type</label><select name="vehicle" id="plan-vehicle"><option>Bike</option><option>Car</option></select></div><div class="form-field"><label for="plan-month">Travel month</label><select name="month" id="plan-month">${MONTHS.map((x,i)=>`<option value="${i}" ${i===10?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="plan-days">Days on the road</label><input id="plan-days" name="days" type="number" min="1" max="60" value="7" required></div><div class="form-field"><label for="plan-people">Travelers</label><input id="plan-people" name="people" type="number" min="1" max="30" value="2" required></div><div class="form-field"><label for="plan-km">Total distance (km)</label><input id="plan-km" name="distance" type="number" min="1" max="20000" value="650" required></div><div class="form-field"><label for="plan-stay">Stay style</label><select id="plan-stay" name="stay"><option>Budget</option><option selected>Comfort</option><option>Premium</option></select></div><div class="form-field"><label for="plan-fuel">Fuel / power source</label><select name="fuel" id="plan-fuel"><option>Petrol</option><option>Diesel</option><option>Hybrid</option><option>Electric</option></select></div><div class="form-field"><label for="plan-mileage" id="mileage-label">Mileage (km/l)</label><input id="plan-mileage" name="mileage" type="number" min="1" max="200" step="0.1" value="${VEHICLES.Bike.mileage}" required></div><div class="form-field"><label for="plan-rate" id="rate-label">Fuel price (₹/liter)</label><input id="plan-rate" name="fuelPrice" type="number" min="1" max="1000" step="0.1" value="${fuelRate()}" required></div><div class="form-field"><label for="plan-seats">Travelers per vehicle</label><input id="plan-seats" name="seats" type="number" min="1" max="${VEHICLES.Bike.maxSeats}" value="${VEHICLES.Bike.seats}" required></div><div class="form-field wide"><label for="plan-preferences">Your interests and requirements (for AI when configured)</label><textarea id="plan-preferences" name="preferences" maxlength="500" placeholder="Photography, vegetarian food, relaxed pace, short walks…"></textarea></div></div><p class="form-footnote">Vehicle count is rounded up from travelers ÷ seats. A convoy uses the same mileage assumption for every vehicle. Edit distance for your return journey. Stay prices are planning assumptions, not live quotes.</p><button class="primary" style="width:100%">Build my trip plan ↗</button></form><section class="panel" id="plan-result" aria-live="polite"><div class="result-placeholder"><div class="planner-art">⌁ ✧</div><h3>A little planning.<br>A lot of possibility.</h3><p>Your per-person costs, places, stays and<br>break suggestions will appear here.</p></div></section></div>`}
function render(){const titles={discover:'Discover',planner:'AI trip planner',groups:'Find your crew',saved:'Saved trips',alerts:'Time alerts'};$('#page-title').textContent=titles[page];document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));if(page==='discover'){main.innerHTML=discover();updateTrips()}if(page==='planner')main.innerHTML=planner();if(page==='saved')main.innerHTML=heading('A little inspiration, saved.','The roads you want to come back to.')+`<div class="trip-grid" style="margin-bottom:35px">${trips.filter(t=>state.saved.includes(t.id)).map(tripCard).join('')||'<div class="empty">Your next adventure is waiting. Tap ♡ on a trip to save it.<br><br><button class="primary" data-page="discover">Discover trips ↗</button></div>'}</div>`;if(page==='groups')main.innerHTML=heading('Find your kind of people.','Shared roads. Shared stories. A community for every kind of explorer.',`<button class="primary" id="create-group">＋ Create a group</button>`)+`<form id="group-search" class="search-panel"><div class="search-field"><label for="group-query">FIND A COMMUNITY</label><input id="group-query" name="query" placeholder="Search by name, city, or vehicle" maxlength="100"></div><button class="primary">Search groups ↗</button></form><p class="results-info">Official community references, sample crews and your local groups. External communities manage membership on their own sites; no member locations are tracked.</p><div class="groups-grid" id="group-results">${allGroups().map(g=>groupRow(g,true)).join('')}</div><p class="form-footnote">Credibility combines profile completeness (25%), completed-trip rate (45%), and reviews (30%). Sample scores are illustrative and do not establish safety. New groups stay unrated until they have evidence.</p>`;if(page==='alerts')main.innerHTML=alertsPage();updateProfile()}
async function loadGarage(){
  try{const response=await fetch('/api/profile',{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error);garage=data;return true}catch{return false}
}
async function profile(){
  if(authLoading){toast('Checking your sign-in. Please wait.');return}
  if(authError){open('<h2>We couldn’t check your session.</h2><p>Please check your connection and try again.</p><button class="primary" id="retry-auth">Try again</button>');return}
  if(!session.user){open(authModal('signin'));return}
  open('<h2>Your explorer profile</h2><p>Loading your profile and vehicles…</p>');
  if(!await loadGarage()){open('<h2>Profile temporarily unavailable.</h2><p>Your existing profile has not been changed. Please retry when the connection is available.</p><button class="primary" id="retry-profile">Try again</button>');return}
  garageDraft=structuredClone(garage.profile);renderProfile();
}
function vehicleFields(v,i){return `<fieldset class="vehicle-editor" data-vehicle-row="${i}"><legend>${vehicleLabel(v.type)} ${i+1}</legend><input type="hidden" name="id" value="${esc(v.id)}"><div class="form-grid"><div class="form-field"><label for="v-type-${i}">Type</label><select name="type" id="v-type-${i}">${['Bike','Car'].map(x=>`<option ${v.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="v-year-${i}">Model year</label><input id="v-year-${i}" name="year" type="number" min="1980" max="${new Date().getFullYear()+1}" value="${v.year}" required></div><div class="form-field"><label for="v-make-${i}">Make</label><input id="v-make-${i}" name="make" maxlength="40" placeholder="Royal Enfield / Maruti" value="${esc(v.make)}" required></div><div class="form-field"><label for="v-model-${i}">Model</label><input id="v-model-${i}" name="model" maxlength="60" placeholder="Himalayan / Jimny" value="${esc(v.model)}" required></div><div class="form-field"><label for="v-fuel-${i}">Fuel type</label><select id="v-fuel-${i}" name="fuel">${['Petrol','Diesel','Hybrid','Electric'].map(x=>`<option ${v.fuel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="v-mileage-${i}">Mileage (km/l; EV: km/kWh)</label><input id="v-mileage-${i}" name="mileage" type="number" min="1" max="200" step="0.1" value="${v.mileage}" required></div><div class="form-field"><label for="v-seats-${i}">Seats (1–${VEHICLES[v.type].maxSeats})</label><input id="v-seats-${i}" name="seats" type="number" min="1" max="8" value="${v.seats}" required></div><div class="form-field"><label for="v-cc-${i}">Engine cc (EV: 0)</label><input id="v-cc-${i}" name="engineCc" type="number" min="0" max="10000" value="${v.engineCc}" required></div></div><button type="button" class="text-link danger" data-remove-vehicle="${i}">Remove this vehicle</button></fieldset>`}
function renderProfile(){
  $('#modal-body').innerHTML=`<div class="eyebrow">YOUR EXPLORER PROFILE</div><h2>${esc(session.user.name)}</h2><p>Signed in with ${providerName()} · profile and garage sync to your account.</p><form id="profile-form"><div class="form-grid"><div class="form-field"><label for="home-city">Home city</label><input id="home-city" name="homeCity" maxlength="80" value="${esc(garageDraft.homeCity)}"></div><div class="form-field"><label for="experience">Experience</label><select id="experience" name="experience">${['Beginner','Intermediate','Experienced'].map(x=>`<option ${garageDraft.experience===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field wide"><label for="profile-bio">About your riding / driving</label><textarea id="profile-bio" name="bio" maxlength="500">${esc(garageDraft.bio)}</textarea></div></div><h3>My garage · ${garageDraft.vehicles.length} / 10 vehicles</h3><p class="form-footnote">Add each bike or car you own. Mileage can be adjusted to your real-world experience.</p>${garageDraft.vehicles.map(vehicleFields).join('')||'<p>No vehicles yet. Add your first ride below.</p>'}<div class="button-row"><button type="button" class="secondary" id="add-vehicle" ${garageDraft.vehicles.length>=10?'disabled':''}>＋ Add a vehicle</button><button class="primary" id="save-profile">Save profile & garage</button></div><p id="profile-status" class="form-footnote" role="status"></p></form><a class="text-link auth-link" href="${session.signOutUrl}" target="_top">Sign out</a>`;
}
function captureProfile(){
  const form=$('#profile-form'),data=new FormData(form);
  return {homeCity:String(data.get('homeCity')||'').trim(),experience:data.get('experience'),bio:String(data.get('bio')||'').trim(),vehicles:[...form.querySelectorAll('[data-vehicle-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('input,select')].map(field=>[field.name,['year','mileage','seats','engineCc'].includes(field.name)?Number(field.value):field.value])))};
}
function authModal(mode){const reg=mode==='register';return `<div class="eyebrow">YOUR JOURNEY STARTS HERE</div><h2>${reg?'Create your Roamly account.':'Your next adventure awaits.'}</h2><p>Sign in to create your profile, add vehicles, and join groups.</p><form id="auth-form" data-mode="${mode}"><div class="form-grid">${reg?'<div class="form-field wide"><label for="auth-name">Name</label><input id="auth-name" name="name" maxlength="60" autocomplete="name" required></div>':''}<div class="form-field wide"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" maxlength="254" autocomplete="email" required></div><div class="form-field wide"><label for="auth-password">Password${reg?' <small>(8+ characters)</small>':''}</label><input id="auth-password" name="password" type="password" minlength="${reg?8:1}" maxlength="128" autocomplete="${reg?'new-password':'current-password'}" required></div></div><p id="auth-status" class="form-footnote" role="status"></p><button class="primary" style="width:100%">${reg?'Create account':'Sign in'}</button></form><p class="form-footnote">${reg?'Already have an account?':'New to Roamly?'} <button type="button" class="text-link" data-auth-mode="${reg?'signin':'register'}">${reg?'Sign in':'Create an account'}</button></p><div class="auth-divider">or continue with</div><div class="login-providers"><a class="secondary" href="${session.signInUrl}" target="_top">ChatGPT ↗</a>${session.googleLogin?'<a class="secondary" href="/api/auth/google" target="_top">Google ↗</a>':''}</div>`}
async function submitAuth(form,d){const reg=form.dataset.mode==='register',status=$('#auth-status'),button=form.querySelector('button.primary');button.disabled=true;status.textContent=reg?'Creating your account…':'Signing in…';
  try{const response=await fetch(reg?'/api/auth/register':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(reg?{name:d.name,email:d.email,password:d.password}:{email:d.email,password:d.password}),signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Please try again.');location.reload()}
  catch(error){status.textContent=error.message||'Please try again.';button.disabled=false}}
function requireSignIn(){if(authLoading||authError||!session.user){profile();return false}return true}
function creation(type){if(!requireSignIn())return;if(type==='trip'){page='planner';render();toast('Start with a route and build your trip plan.');return}open(`<h2>Good company starts here.</h2><p>Create a demo group for your next adventure.</p><form id="group-form"><div class="form-grid"><div class="form-field wide"><label for="new-name">Group name</label><input id="new-name" name="name" required maxlength="60"></div><div class="form-field"><label for="new-city">Home city</label><input id="new-city" name="city" required maxlength="60"></div><div class="form-field"><label for="new-vehicle">Your ride</label><select id="new-vehicle" name="vehicle"><option>Bike</option><option>Car</option></select></div><div class="form-field wide"><label for="new-meetup">Meeting area</label><input id="new-meetup" name="meetup" maxlength="100" required placeholder="City area or public meeting point"></div><div class="form-field wide"><label for="new-cadence">Ride cadence / meetup time</label><input id="new-cadence" name="cadence" maxlength="100" required placeholder="Sunday mornings, 06:30 — confirm each ride"></div><div class="form-field wide"><label for="new-description">What's your group about?</label><textarea id="new-description" name="description" required maxlength="300"></textarea></div>${Object.entries({instagram:'instagram.com/yourgroup',youtube:'youtube.com/@yourchannel',facebook:'facebook.com/groups/yourgroup',website:'yourgroup.in'}).map(([k,ph])=>`<div class="form-field"><label for="new-${k}">${LINK_KINDS[k].label} <small>(optional)</small></label><input id="new-${k}" name="${k}" type="text" inputmode="url" maxlength="200" placeholder="${ph}"></div>`).join('')}<button class="primary">Create demo group ↗</button></div></form>`)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;handleExtraClick(el);if(el.dataset.page){page=el.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'})}if(el.dataset.filter){filter.vehicle=el.dataset.filter;render()}if(el.dataset.season){filter.season=el.dataset.season;filter.query='';filter.vehicle='All';page='discover';render();$('#search-form').scrollIntoView({behavior:'smooth',block:'start'})}if(el.dataset.save){if(authLoading)return toast('Please wait while your session loads.');if(authError){profile();return}const id=el.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'A new adventure, saved.':'Trip removed from saved.')}if(el.dataset.trip){showTrip(el.dataset.trip)}if(el.dataset.plan){modal.close();page='planner';render();$('#plan-route').value=el.dataset.plan;syncRoute()}if(el.dataset.join){if(!requireSignIn())return;const id=el.dataset.join;state.joined=state.joined.includes(id)?state.joined.filter(x=>x!==id):[...state.joined,id];persist();if(modal.open)modal.close();render();toast(state.joined.includes(id)?'You joined this group in the demo.':'You left this demo group.')}if(el.dataset.score){const g=allGroups().find(g=>g.id===el.dataset.score);open(`<h2>${esc(g.name)}</h2>${isSample(g.id)?`<p>Illustrative credibility score: <strong>${credibility(g)} / 100</strong></p><div class="cost-row">Profile completeness (25%) <strong>${g.profile}%</strong></div><div class="cost-row">Completed-trip rate (45%) <strong>${g.completion}%</strong></div><div class="cost-row">Member reviews (30%) <strong>${g.reviews}%</strong></div><p>These are sample signals, not verified records. No score guarantees a safe trip or a trustworthy organizer.</p>`:'<p>This group is unrated. No completed-trip records or member reviews have been collected.</p>'}`)}if(['profile-button','auth-button','planner-profile','retry-profile'].includes(el.id))profile();if(el.id==='retry-auth'){modal.close();authLoading=true;authError=false;updateProfile();loadSession();}if(el.id==='create-top')creation('trip');if(el.id==='create-group')creation('group');if(el.classList.contains('modal-close'))modal.close();if(el.id==='help-button')open('<h2>A preview of the open road.</h2><p>Roamly is a working local-data prototype. Discover sample routes, save favorites, sign in with ChatGPT, join sample communities, and build transparent trip estimates.</p><p>The planner shows per-person estimates and curated places, stays and breaks. Optional AI suggestions become available after service setup. Social buttons open searches on external platforms; they do not import private groups, track members, or verify social profiles.</p><p>Sign-in uses a server-checked ChatGPT identity. Your profile and vehicles are stored in your account. Saved trips, demo groups and reminders stay in this browser. Map links open external searches; social imports, live weather and Meta login are not enabled.</p>')});
function syncRoute(){const t=trips.find(t=>t.id===$('#plan-route').value);$('#plan-days').value=t.days;$('#plan-km').value=t.km;$('#plan-vehicle').value=t.vehicle;$('#plan-garage').value='';resetVehicle()}
function resetVehicle(){const v=VEHICLES[$('#plan-vehicle').value];$('#plan-mileage').value=v.mileage;$('#plan-seats').value=v.seats;$('#plan-seats').max=v.maxSeats;$('#plan-fuel').value='Petrol';$('#plan-rate').value=fuelRate('Petrol');fuelLabels()}
function fuelLabels(){const ev=$('#plan-fuel').value==='Electric';$('#mileage-label').textContent=ev?'Efficiency (km/kWh)':'Mileage (km/l)';$('#rate-label').textContent=ev?'Charging cost (₹/kWh)':'Fuel price (₹/liter)'}
document.addEventListener('change',e=>{if(e.target.closest('[data-vehicle-row]')&&e.target.name==='type'){const row=e.target.closest('[data-vehicle-row]'),max=VEHICLES[e.target.value].maxSeats;row.querySelector('legend').textContent=vehicleLabel(e.target.value)+' '+(Number(row.dataset.vehicleRow)+1);const seats=row.querySelector('[name=seats]');seats.max=max;row.querySelector('label[for="'+seats.id+'"]').textContent='Seats (1–'+max+')'}if(e.target.id==='plan-route')syncRoute();if(e.target.id==='plan-vehicle'){ $('#plan-garage').value='';resetVehicle()}if(e.target.id==='plan-fuel'){fuelLabels();$('#plan-rate').value=fuelRate(e.target.value)}if(e.target.id==='plan-garage'){const v=garage?.profile.vehicles.find(v=>v.id===e.target.value);if(v){$('#plan-vehicle').value=v.type;$('#plan-mileage').value=v.mileage;$('#plan-seats').value=v.seats;$('#plan-seats').max=VEHICLES[v.type].maxSeats;$('#plan-fuel').value=v.fuel;$('#plan-rate').value=fuelRate(v.fuel);fuelLabels()}}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,formId=f.getAttribute('id'),d=Object.fromEntries(new FormData(f));if(formId==='search-form'){filter={query:d.query.trim(),vehicle:d.vehicle,season:d.season};updateTrips();document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter.vehicle))}if(formId==='group-form'){if(!requireSignIn())return;if(!d.name.trim()||!d.city.trim()||!d.description.trim()||!d.meetup.trim()||!d.cadence.trim())return toast('Please fill in all group details.');const id='group-'+crypto.randomUUID();const {links,error}=cleanLinks(d);if(error)return toast(error);
state.groups.push({id,links,name:d.name.trim(),city:d.city.trim(),vehicle:d.vehicle,description:d.description.trim(),meetup:d.meetup.trim(),cadence:d.cadence.trim(),organizer:session.user.name,members:0,icon:'♧'});state.joined.push(id);persist();modal.close();page='groups';render();toast('Your demo crew is ready.')}if(formId==='group-search'){const q=d.query.toLowerCase().trim();const gs=allGroups().filter(g=>`${g.name} ${g.city} ${g.vehicle}`.toLowerCase().includes(q));$('#group-results').innerHTML=gs.map(g=>groupRow(g,true)).join('')||'<div class="empty">No matching crews. Try another city or create your own.</div>'}if(formId==='planner-form'){buildPlan(d)}if(formId==='profile-form'){saveGarage(f)}if(formId==='alert-form'){addCustomAlert(d)}if(formId==='auth-form'){submitAuth(f,d)}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
const mapLink=q=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);
const pp=value=>'₹'+Number(value).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
function placeCards(t){return `<div class="place-grid">${t.places.map(p=>`<article class="place-card"><h4>${esc(p.name)}</h4><p>Allow about ${p.minutes} minutes. Optional sightseeing stop; allow extra time for access and queues.</p><a class="text-link" href="${mapLink(p.name)}" target="_blank" rel="noopener noreferrer">Find on Google Maps ↗</a></article>`).join('')}</div>`}
function stayCards(t){return `<div class="place-grid">${t.stays.map(s=>`<article class="place-card"><h4>${esc(s.area)}</h4><p>${esc(s.type)} · illustrative ${money(s.min)}–${money(s.max)} / room / night.</p><a class="text-link" href="${mapLink('hotels and homestays in '+s.area)}" target="_blank" rel="noopener noreferrer">Find stays & current prices ↗</a></article>`).join('')}</div><p class="form-footnote">Suggested areas, not booked or verified properties. Check secure parking, check-in, reviews and availability directly.</p>`}
function stopCards(t){return `<div class="place-grid">${t.stops.map(s=>`<article class="place-card"><h4>${esc(s.name)}</h4><p>${esc(s.purpose)}</p><a class="text-link" href="${mapLink('restaurants fuel stations charging in '+s.name)}" target="_blank" rel="noopener noreferrer">Search facilities ↗</a></article>`).join('')}</div>`}
function showTrip(id){const t=trips.find(t=>t.id===id);if(!t)return;open(`<img class="detail-img" src="${photo(t.image)}" alt="Illustrative road-trip landscape"><div class="eyebrow">${esc(t.tag)}</div><h2>${esc(t.title)}</h2><p>${esc(t.desc)}</p><div class="detail-facts"><span>${esc(t.route)}</span><span>${t.days} days · approximately ${t.km} km</span><span>Typical travel months: ${esc(travelWindow(t))}</span></div><div class="notice">${esc(t.risk)} Verify current conditions before departure.</div><h3>Places to visit</h3>${placeCards(t)}<h3>Rest & food stops</h3>${stopCards(t)}<h3>Where to stay</h3>${stayCards(t)}<p>Starting planning budget: <strong>${money(tripPrice(t))} per person</strong> (2 travelers, Comfort stays). <a class="text-link" href="${t.source}" target="_blank" rel="noopener noreferrer">Tourism reference ↗</a></p><button class="primary" data-plan="${t.id}">Plan this route ↗</button>`)}
async function saveGarage(form){
  const button=$('#save-profile'),status=$('#profile-status');
  garageDraft=captureProfile();button.disabled=true;status.textContent='Saving your profile…';
  try{const response=await fetch('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:garageDraft,updatedAt:garage.updatedAt})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Profile could not be saved.');garage=data;status.textContent='Profile and all vehicles saved to your account.';toast('Your garage is saved.');if(page==='planner')render()}
  catch(error){status.textContent=error.message}
  finally{button.disabled=false}
}
function dayPlanHtml(t,days,aiPlan=null){
  const sequence=aiPlan?aiPlan.days.map(d=>({...d,places:d.placeIds.map(id=>t.places.find(p=>p.id===id)),stay:{area:d.stayArea},stop:{name:d.breakNote}})):outline(t,days);
  return sequence.map(d=>`<article class="plan-day"><strong>Day ${d.day} · ${esc(d.focus)}</strong><p>${d.places.length?d.places.map(p=>`<a href="${mapLink(p.name)}" target="_blank" rel="noopener noreferrer">${esc(p.name)} ↗</a> (~${p.minutes} min)`).join(' · '):'Keep this day flexible for travel, acclimatization or rest.'}</p><p>Break: ${esc(d.stop.name)}. Stop sooner whenever fatigue or conditions require it.</p>${d.day<days?`<p>Stay search area: <a href="${mapLink('hotels in '+d.stay.area)}" target="_blank" rel="noopener noreferrer">${esc(d.stay.area)} ↗</a></p>`:'<p>Final-day onward or return travel is not automatically included. Adjust distance and add a night if needed.</p>'}</article>`).join('');
}
function buildPlan(data){
  try{
    const t=trips.find(t=>t.id===data.route);if(!t)throw new Error('Choose a valid route.');
    const d={...data,days:Number(data.days),people:Number(data.people),distance:Number(data.distance),mileage:Number(data.mileage),seats:Number(data.seats),fuelPrice:Number(data.fuelPrice),month:Number(data.month)};
    const r=estimate(d);latestPlan={trip:t,data:d,result:r};
    const categories=[['Fuel / charging',r.fuel],['Accommodation',r.accommodation],['Food',r.food],['Tolls, parking & activities',r.extras],['Contingency · 15%',r.contingency]];
    $('#plan-result').innerHTML=`<div class="eyebrow">YOUR ESCAPE, ON PAPER</div><h3 style="margin-top:9px">${esc(t.title)}</h3><div class="budget-tiles"><div><small>GROUP ESTIMATE</small><strong>${money(r.total)}</strong></div><div><small>PER PERSON · ${d.people} TRAVELERS</small><strong>${pp(r.total/d.people)}</strong></div></div><p class="form-footnote">${d.days} days · ${r.vehicles} ${d.vehicle.toLowerCase()}${r.vehicles>1?'s':''} · ${esc(d.stay)} stays · ${d.distance} km · ${d.mileage} ${d.fuel==='Electric'?'km/kWh':'km/l'}</p><table class="cost-table"><thead><tr><th>Category</th><th>Group</th><th>Per person</th></tr></thead><tbody>${categories.map(([label,value])=>`<tr><td>${label}</td><td>${money(value)}</td><td>${pp(value/d.people)}</td></tr>`).join('')}<tr class="total"><td>Total</td><td>${money(r.total)}</td><td>${pp(r.total/d.people)}</td></tr></tbody></table><p class="form-footnote">Equal split among all travelers; rounded to two decimals per person. These are estimates, not quotes. ${d.days-1} nights, two people per room; food ₹650/person/day; extras ₹200/person/day plus ₹${VEHICLES[d.vehicle].perKm.toFixed(2)}/km/vehicle. Fuel or power price: ${money(d.fuelPrice)} per ${d.fuel==='Electric'?'kWh':'liter'}.</p><div class="notice">${t.months.includes(d.month)?'This month broadly matches the listed travel window.':'This month is outside the typical travel window ('+esc(travelWindow(t))+'). Consider another date or route.'} ${esc(t.risk)}</div>${d.days<t.days?`<p class="notice">This route usually needs about ${t.days} days. Your ${d.days}-day outline may be too rushed; add days or shorten the route.</p>`:''}<h3 class="subheading">Places to visit</h3>${placeCards(t)}<h3 class="subheading">Stay areas</h3>${stayCards(t)}<h3 class="subheading">Food, fuel & rest stops</h3>${stopCards(t)}<div class="section-heading subheading"><h3>Daily outline</h3><span id="plan-source" class="eyebrow">CURATED DRAFT</span></div><div id="daily-plan">${dayPlanHtml(t,d.days)}</div><div id="ai-tips"></div><p class="form-footnote" id="ai-status">${aiAvailable?'Optionally use your interests to reorganize this draft with AI. Only route and travel preferences are sent, not your profile or vehicle identifiers.':'Live AI is not configured. This is a curated planning draft, with useful places and stop suggestions.'}</p><div class="button-row"><button class="secondary" id="request-ai" ${!aiAvailable||d.days>30?'disabled':''}>✧ Suggest with AI</button><button class="secondary" id="plan-alerts">◷ Set time alerts</button><button class="primary" id="download-plan">↓ Download plan</button></div><p class="form-footnote">No live route optimization, bookings or traffic data. Check facilities, opening hours, detours and current road access. <a href="${t.source}" target="_blank" rel="noopener noreferrer">Tourism reference ↗</a></p>`;
    if(innerWidth<850)$('#plan-result').scrollIntoView({behavior:'smooth'});
  }catch(error){toast(error.message)}
}
async function requestAI(){
  if(!requireSignIn()||!latestPlan)return;
  const button=$('#request-ai'),status=$('#ai-status'),current=latestPlan;button.disabled=true;status.textContent='Preparing AI suggestions…';
  try{const d=current.data,response=await fetch('/api/ai-plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({routeId:current.trip.id,days:d.days,people:d.people,vehicle:d.vehicle,month:d.month,preferences:d.preferences||''}),signal:AbortSignal.timeout(35000)});const data=await response.json();if(!response.ok)throw new Error(data.error);if(latestPlan!==current||!$('#daily-plan'))return;$('#daily-plan').innerHTML=dayPlanHtml(current.trip,d.days,data.plan);$('#ai-tips').innerHTML='<h3 class="subheading">AI considerations</h3>'+data.plan.tips.map(t=>`<p class="form-footnote">${esc(t)}</p>`).join('');$('#plan-source').textContent='AI DRAFT · REVIEW REQUIRED';status.textContent='AI draft generated using the curated route. Confirm feasibility and current conditions before travel.'}
  catch(error){if($('#ai-status'))$('#ai-status').textContent=error.message||'AI is unavailable. Your curated plan is still available.'}
  finally{if($('#request-ai'))$('#request-ai').disabled=false}
}
function downloadFile(name,text,type='text/plain'){
  const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function alertsPage(){
  const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone;
  return heading('A little reminder goes a long way.','Departure, rest breaks and check-ins — timed around your journey.')+`<div class="notice">In-app alerts work while this page is open and may be delayed by device sleep. For reminders when Roamly is closed, download and import the calendar file into your calendar app, then check its notification settings.</div><div class="planner-layout subheading"><form id="alert-form" class="panel"><h3>Add a reminder</h3><div class="form-grid"><div class="form-field wide"><label for="alert-label">Reminder</label><input id="alert-label" name="label" maxlength="120" required placeholder="Leave for the meetup / take a rest break"></div><div class="form-field wide"><label for="alert-time">Date and time (${esc(timezone)})</label><input id="alert-time" name="at" type="datetime-local" required></div></div><p class="form-footnote">Alerts are stored in this browser for your current account. Calendar exports use UTC to preserve the selected instant across time zones.</p><button class="primary">Add time alert</button></form><section class="panel"><h3>Upcoming & recent alerts</h3><div class="button-row"><button class="secondary" id="export-alerts" ${state.alerts.length?'':'disabled'}>↓ Calendar (.ics)</button><button class="secondary" id="enable-notifications">Enable browser notifications</button></div>${state.alerts.length?state.alerts.slice().sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)).map(a=>`<article class="alert-row"><div><strong>${esc(a.label)}</strong><p>${esc(new Date(a.at).toLocaleString())} · ${a.fired?'Due / delivered':'Scheduled'}</p></div><button class="text-link danger" data-delete-alert="${esc(a.id)}">Remove</button></article>`).join(''):'<p class="form-footnote">No alerts yet. Add one here or generate departure and rest reminders from a trip plan.</p>'}</section></div>`;
}
function addCustomAlert(data){
  const at=new Date(data.at).getTime();if(!data.label.trim()||!Number.isFinite(at)||at<=Date.now())return toast('Enter a reminder and a future date and time.');
  if(state.alerts.length>=500)return toast('Remove some old alerts before adding more.');
  state.alerts.push({id:crypto.randomUUID(),label:data.label.trim(),at:new Date(at).toISOString(),fired:false});persist();render();toast('Time alert added. Keep this page open or export to your calendar.');
}
function schedulePlan(){if(!latestPlan)return;const time=new Date(Date.now()+86400000);time.setHours(6,0,0,0);const local=new Date(time.getTime()-time.getTimezoneOffset()*60000).toISOString().slice(0,16);open(`<h2>Set trip reminders</h2><p>Daily reminders for departure, a break after 2 hours, lunch after 4 hours and check-in after 8 hours. Adjust these to your real schedule in your calendar.</p><div class="form-field"><label for="trip-departure">First departure (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)})</label><input id="trip-departure" type="datetime-local" value="${local}" required></div><p class="form-footnote">${latestPlan.data.days} days × 4 reminders. In-app alerts need this page open; calendar reminders can work after it closes.</p><button class="primary" id="confirm-trip-alerts">Create reminders</button>`)}
function checkAlerts(){
  if(authLoading||authError)return;let changed=false;
  for(const alert of state.alerts){if(!alert.fired&&Date.parse(alert.at)<=Date.now()){alert.fired=true;changed=true;toast(alert.label);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('Roamly time alert',{body:alert.label,tag:alert.id})}catch{}}}}
  if(changed){persist();if(page==='alerts')render()}
  const due=state.alerts.filter(a=>a.fired&&!a.dismissed),banner=$('#alert-banner');
  banner.hidden=!due.length;banner.innerHTML=due.length?`<strong>◷ ${due.length} reminder${due.length===1?'':'s'} due</strong><p>${due.slice(-3).map(a=>esc(a.label)).join('<br>')}</p><button class="text-link" id="dismiss-due">Dismiss delivered reminders</button> · <button class="text-link" data-page="alerts">View all alerts</button>`:'';
}
function showGroup(id){const g=allGroups().find(x=>x.id===id);if(!g)return;if(g.external){open(`<div class="eyebrow">PUBLIC COMMUNITY DIRECTORY</div><h2>${esc(g.name)}</h2><p>${esc(g.description)}</p><div class="detail-facts"><span>${esc(g.city)}</span><span>${g.vehicle}</span><span>Credibility: unrated</span></div><p>Membership, fees, current meetups and ride eligibility must be checked directly with the community. Roamly has not verified members or safety records and is not affiliated with this group.</p><a class="primary auth-link" href="${g.website}" target="_blank" rel="noopener noreferrer">Visit official community ↗</a>`);return}const detail=groupDetails[g.id]||{organizer:g.organizer||'Group creator',meetup:g.meetup||g.city,cadence:g.cadence||'Ask the organizer',experience:g.experience||'All experience levels',routes:[],rules:['Agree the route, meetup and emergency plan with the organizer.','Wear appropriate protective equipment and follow road rules.']};open(`<div class="eyebrow">${isSample(id)?'SAMPLE COMMUNITY · DETAILS ARE ILLUSTRATIVE':'BROWSER-LOCAL COMMUNITY'}</div><h2>${esc(g.name)}</h2><p>${esc(g.description)}</p><div class="detail-facts"><span>${esc(g.city)}</span><span>${g.vehicle} · ${Number(g.members)+(state.joined.includes(id)?1:0)} members</span><span>${esc(detail.experience)}</span></div><dl class="group-facts"><dt>Organizer</dt><dd>${esc(detail.organizer)}</dd><dt>Meetup area</dt><dd><a href="${mapLink(detail.meetup)}" target="_blank" rel="noopener noreferrer">${esc(detail.meetup)} ↗</a></dd><dt>Ride cadence</dt><dd>${esc(detail.cadence)}</dd></dl>${ownLinks(g)?`<div class="group-links">${ownLinks(g)}</div>`:''}<h3>Riding / driving expectations</h3><ul>${detail.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><h3>Routes this crew is into</h3>${detail.routes.length?detail.routes.map(id=>{const t=trips.find(t=>t.id===id);return t?`<div class="alert-row"><span>${esc(t.title)}<small> · ${money(tripPrice(t))} / person estimate</small></span><button class="text-link" data-plan="${t.id}">Plan ↗</button></div>`:''}).join(''):'<p>No specific routes listed yet. Agree a trip with the organizer.</p>'}<p class="form-footnote">No live meetup or trip date has been verified. Home cities and meeting areas are not live member locations.</p><button class="primary" data-join="${esc(id)}">${state.joined.includes(id)?'Leave this group':'Join this group'}</button>`)}
const groupDetails={weekend:{organizer:'Roamly demo host · Bengaluru',meetup:'Hebbal, Bengaluru',cadence:'Saturday mornings · confirm each ride',experience:'Beginner friendly',routes:['coorg','hampi','ooty'],rules:['Helmet and protective riding gear required.','Keep a lead and sweep rider; regroup at agreed stops.','No racing. Carry water, tools and a puncture kit.']},overland:{organizer:'Roamly demo host · Mumbai',meetup:'Vashi, Navi Mumbai',cadence:'One weekend convoy per month · illustrative',experience:'Intermediate',routes:['konkan','goa','kutch'],rules:['Seat belts for everyone and no phone use while driving.','Share fuel and toll assumptions before departure.','Respect convoy spacing and agree rest stops.']},himalayan:{organizer:'Roamly demo host · Delhi',meetup:'India Gate area, New Delhi',cadence:'Seasonal mountain expeditions · confirm dates',experience:'Experienced mountain riders',routes:['spiti','ladakh','rishikesh'],rules:['Allow acclimatization and a weather buffer.','Check vehicle condition and fuel range before remote sections.','Confirm permits, first-aid arrangements and local access.']}};
function handleExtraClick(el){
  if(el.dataset.authMode){$('#modal-body').innerHTML=authModal(el.dataset.authMode);$('#auth-form input').focus()}
  if(el.id==='add-vehicle'){garageDraft=captureProfile();if(garageDraft.vehicles.length>=10)return;garageDraft.vehicles.push({id:crypto.randomUUID(),type:'Bike',make:'',model:'',year:new Date().getFullYear(),fuel:'Petrol',mileage:VEHICLES.Bike.mileage,seats:VEHICLES.Bike.seats,engineCc:350});renderProfile()}
  if(el.dataset.removeVehicle!==undefined){garageDraft=captureProfile();garageDraft.vehicles.splice(Number(el.dataset.removeVehicle),1);renderProfile()}
  if(el.dataset.group)showGroup(el.dataset.group);
  if(el.id==='request-ai')requestAI();
  if(el.id==='download-plan'&&$('#plan-result'))downloadFile('roamly-trip-plan.txt',$('#plan-result').innerText);
  if(el.id==='plan-alerts')schedulePlan();
  if(el.id==='confirm-trip-alerts'){try{const alerts=tripAlerts({title:latestPlan.trip.title,departure:$('#trip-departure').value,days:latestPlan.data.days});if(state.alerts.length+alerts.length>500)throw new Error('Remove old alerts before creating more (500 maximum).');state.alerts.push(...alerts);persist();modal.close();page='alerts';render();toast('Trip reminders created. Export them to your calendar for alerts when the app is closed.')}catch(error){toast(error.message)}}
  if(el.id==='export-alerts'){const future=state.alerts.filter(a=>Date.parse(a.at)>Date.now());if(!future.length)return toast('There are no future alerts to export.');downloadFile('roamly-reminders.ics',calendar(future),'text/calendar')}
  if(el.dataset.deleteAlert){state.alerts=state.alerts.filter(a=>a.id!==el.dataset.deleteAlert);persist();render();checkAlerts()}
  if(el.id==='dismiss-due'){state.alerts.forEach(a=>{if(a.fired)a.dismissed=true});persist();checkAlerts()}
  if(el.id==='enable-notifications'){if(!('Notification'in window))return toast('Browser notifications are not supported here. Use the calendar export.');Notification.requestPermission().then(p=>toast(p==='granted'?'Notifications enabled while Roamly is running.':'Notifications were not enabled. In-app alerts and calendar export are still available.')).catch(()=>toast('Use calendar export for reminders on this device.'))}
}
setInterval(checkAlerts,15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkAlerts()});

if(new URLSearchParams(location.search).get('login_error')==='google'){history.replaceState(null,'',location.pathname+location.hash);setTimeout(()=>toast('Google sign-in did not complete. Please try again.'),0)}
render();
loadSession();
